import { env } from '../config/env.js';
import { prisma } from './prisma.js';

/**
 * Guards against a silent, permanent timestamp skew.
 *
 * Prisma Client always sends DateTime values as explicit UTC, so every row the
 * app writes is correct regardless of where the server lives. But 64 columns
 * carry a `DEFAULT CURRENT_TIMESTAMP(3)` (generated by `@default(now())`), and
 * that default is evaluated by the *database server* using its own time zone.
 * MySQL ships with `time_zone = SYSTEM`; on a host set to EAT/UTC+3 the default
 * writes 10:00 when the real UTC time is 07:00, and Prisma then reads it back
 * as if it were UTC — three hours wrong, forever, with no error anywhere.
 *
 * The default only fires when a row is inserted without Prisma supplying the
 * value: raw SQL, a seed script, a manual console insert, a restored dump. Rare
 * enough to stay unnoticed, common enough to eventually happen. So check at boot
 * rather than waiting to discover skewed rows later.
 *
 * The same reasoning applies after a move to Postgres: `now()` there is
 * likewise server-evaluated, so the check is provider-aware rather than
 * MySQL-only.
 */

const SKEW_TOLERANCE_SECONDS = 2;

function isPostgres(): boolean {
  return /^postgres(ql)?:\/\//i.test(env.DATABASE_URL);
}

async function readServerClockSkewSeconds(): Promise<number> {
  // Cast to CHAR/text so the driver hands back a plain string rather than a
  // BigInt or Decimal, which differ between connectors.
  const rows = isPostgres()
    ? await prisma.$queryRawUnsafe<Array<{ skew: string }>>(
        `SELECT CAST(EXTRACT(EPOCH FROM (LOCALTIMESTAMP - (now() AT TIME ZONE 'utc'))) AS TEXT) AS skew`
      )
    : await prisma.$queryRawUnsafe<Array<{ skew: string }>>(
        `SELECT CAST(TIMESTAMPDIFF(SECOND, UTC_TIMESTAMP(), CURRENT_TIMESTAMP(3)) AS CHAR) AS skew`
      );

  return Math.round(Number(rows[0]?.skew ?? 0));
}

export async function assertDatabaseIsUtc(): Promise<void> {
  let skew: number;
  try {
    skew = await readServerClockSkewSeconds();
  } catch (error) {
    console.warn('⚠️  Could not verify database time zone:', error);
    return;
  }

  if (Math.abs(skew) <= SKEW_TOLERANCE_SECONDS) {
    console.log('🕐 Database time zone: UTC ✅');
    return;
  }

  const hours = (skew / 3600).toFixed(1);
  const fix = isPostgres()
    ? `ALTER DATABASE <db> SET timezone TO 'UTC';`
    : `SET GLOBAL time_zone = '+00:00';  -- and add "default-time-zone='+00:00'" to my.cnf so it survives restart`;

  console.error(
    [
      '',
      '╔═══════════════════════════════════════════════════════════════════╗',
      '║  ⚠️  DATABASE TIME ZONE IS NOT UTC                                 ║',
      '╚═══════════════════════════════════════════════════════════════════╝',
      `  The database server clock is ${hours}h off UTC (${skew}s).`,
      '',
      '  Rows written by Prisma are still correct — it sends explicit UTC.',
      `  But any insert that lets a column default fire will be ${hours}h wrong,`,
      '  and nothing will report it. Fix with:',
      '',
      `    ${fix}`,
      '',
    ].join('\n')
  );
}
